            {viewMode === 'camera' && (
                <div className="absolute inset-0 z-50 bg-black">
                   <CameraScanner onCapture={async (b64) => { 
                       const id = crypto.randomUUID(); const res = await fetch(`data:image/jpeg;base64,${b64}`);
                       const blob = await res.blob(); filesMap.current.set(id, blob);
                       const previewUrl = URL.createObjectURL(blob);
                       setTasks(prev => [...prev, { id, fileName: `SCAN_${Date.now()}`, status: 'pending', progress: 0, batchIndex: 1, previewUrl }]);
                       setViewMode('file'); 
                   }} onClose={() => setViewMode('file')} isMobile={isMobile} />
                </div>
            )}

            {viewMode === 'cropper' && cropperImage && (
               <div className="absolute inset-0 z-40 bg-slate-100 flex flex-col" onMouseMove={handleCropMove} onMouseUp={handleCropEnd} onTouchMove={handleCropMove} onTouchEnd={handleCropEnd}>
                   <div className="h-14 bg-white border-b border-slate-200 px-6 flex items-center justify-between shrink-0">
                       <div className="font-bold text-slate-700">智慧裁切 ({cropRegions.length})</div>
                       <div className="flex gap-2">
                           {pdfDoc && <div className="flex items-center gap-1 bg-slate-100 rounded-lg p-1 mr-2"><button disabled={currentPdfPage<=1} onClick={()=>{setCurrentPdfPage(p=>p-1);renderPdfPage(pdfDoc,currentPdfPage-1)}} className="w-6 h-6 rounded hover:bg-white"><i className="fa-solid fa-chevron-left text-xs"></i></button><span className="text-xs font-mono px-2">{currentPdfPage}/{pdfDoc.numPages}</span><button disabled={currentPdfPage>=pdfDoc.numPages} onClick={()=>{setCurrentPdfPage(p=>p+1);renderPdfPage(pdfDoc,currentPdfPage+1)}} className="w-6 h-6 rounded hover:bg-white"><i className="fa-solid fa-chevron-right text-xs"></i></button></div>}
