                                                <div className="absolute -bottom-1 -right-1 w-3 h-3 bg-indigo-500 cursor-se-resize rounded-full shadow-sm" onMouseDown={(e)=>{e.stopPropagation();handleCropStart(e,'resize',crop.id,'br')}}></div>
