interface CropRegion {
  id: string;
  x: number;
  y: number;
  w: number;
  h: number;
}

// Helper to find object value by case-insensitive key
const getValue = (row: any, keys: string[]): string | undefined => {
    const rowKeys = Object.keys(row);
    for (const k of keys) {
        const match = rowKeys.find(rk => rk.toLowerCase() === k.toLowerCase());
        if (match && row[match]) return String(row[match]).trim();
    }
    return undefined;
};

// --- Tour Component ---
interface TourStep {
    targetId: string;
    title: string;
    content: string;
    position: 'right' | 'bottom' | 'bottom-left' | 'bottom-right';
}

const TourOverlay: React.FC<{ 
    stepIndex: number; 
    steps: TourStep[]; 
    onNext: () => void; 
    onSkip: () => void; 
}> = ({ stepIndex, steps, onNext, onSkip }) => {
    const [targetRect, setTargetRect] = useState<DOMRect | null>(null);
    const currentStep = steps[stepIndex];

    useEffect(() => {
        const updateRect = () => {
            const el = document.getElementById(currentStep.targetId);
            if (el) {
                setTargetRect(el.getBoundingClientRect());
            }
        };
        updateRect();
        window.addEventListener('resize', updateRect);
        // Add a small delay to allow UI to settle
        setTimeout(updateRect, 100);
        return () => window.removeEventListener('resize', updateRect);
    }, [stepIndex, currentStep.targetId]);

    if (!targetRect) return null;

    // Calculate position for the tooltip
    let tooltipStyle: React.CSSProperties = {};
    if (currentStep.position === 'right') {
        tooltipStyle = { top: targetRect.top, left: targetRect.right + 16 };
    } else if (currentStep.position === 'bottom') {
        tooltipStyle = { top: targetRect.bottom + 16, left: targetRect.left + (targetRect.width/2) - 120 };
    } else if (currentStep.position === 'bottom-left') {
        tooltipStyle = { top: targetRect.bottom + 16, left: targetRect.left };
    } else if (currentStep.position === 'bottom-right') {
        tooltipStyle = { top: targetRect.bottom + 16, right: window.innerWidth - targetRect.right };
    }

    return (
        <div className="fixed inset-0 z-[9999] overflow-hidden">
            {/* Cutout Mask using SVG */}
            <svg className="absolute inset-0 w-full h-full pointer-events-none">
                <defs>
                    <mask id="tour-mask">
                        <rect x="0" y="0" width="100%" height="100%" fill="white" />
                        <rect 
                            x={targetRect.left - 4} 
                            y={targetRect.top - 4} 
                            width={targetRect.width + 8} 
                            height={targetRect.height + 8} 
                            rx="8" 
                            fill="black" 
                        />
                    </mask>
                </defs>
                <rect x="0" y="0" width="100%" height="100%" fill="rgba(0,0,0,0.7)" mask="url(#tour-mask)" />
            </svg>

            {/* Pulsing Border around target */}
            <div 
                className="absolute border-2 border-indigo-400 rounded-lg shadow-[0_0_15px_rgba(99,102,241,0.6)] animate-pulse pointer-events-none"
                style={{
                    top: targetRect.top - 4,
                    left: targetRect.left - 4,
                    width: targetRect.width + 8,
                    height: targetRect.height + 8
                }}
            />

            {/* Tooltip Card */}
            <div 
                className="absolute bg-white p-5 rounded-2xl shadow-2xl max-w-xs animate-fadeIn flex flex-col gap-3"
                style={tooltipStyle}
            >
                <div>
                    <h3 className="text-sm font-bold text-slate-800 mb-1">{currentStep.title}</h3>
                    <p className="text-xs text-slate-500 leading-relaxed">{currentStep.content}</p>
                </div>
                <div className="flex items-center justify-between mt-2">
                    <button onClick={onSkip} className="text-[10px] font-bold text-slate-400 hover:text-slate-600">跳過教學</button>
                    <button 
                        onClick={onNext} 
                        className="bg-indigo-600 text-white px-4 py-1.5 rounded-lg text-xs font-bold shadow-lg shadow-indigo-200 hover:bg-indigo-700 active:scale-95 transition-all"
                    >
                        {stepIndex === steps.length - 1 ? '開始使用' : '下一步'}
                    </button>
                </div>
                {/* Arrow */}
                <div className="absolute w-3 h-3 bg-white transform rotate-45 -z-10" 
                     style={{
                         top: currentStep.position.includes('bottom') ? -6 : 'auto',
                         left: currentStep.position === 'right' ? -6 : (currentStep.position === 'bottom-left' ? 20 : (currentStep.position === 'bottom-right' ? 'auto' : '50%')),
                         right: currentStep.position === 'bottom-right' ? 20 : 'auto',
                         marginTop: currentStep.position === 'right' ? 10 : 0,
                         marginLeft: currentStep.position === 'bottom' ? -6 : 0
                     }}
                ></div>
            </div>
        </div>
    );
};

