                                         }} 
                                         onMouseDown={(e)=>{e.stopPropagation();handleCropStart(e,'move',crop.id)}}
                                    >
                                        {/* Active Crop Border & Controls */}
                                        {activeCropId === crop.id && (
                                            <div className="absolute inset-0 border-2 border-indigo-500">
                                                <div className="absolute -top-1 -left-1 w-3 h-3 bg-indigo-500 cursor-nw-resize rounded-full shadow-sm" onMouseDown={(e)=>{e.stopPropagation();handleCropStart(e,'resize',crop.id,'tl')}}></div>
                                                <div className="absolute -top-1 -right-1 w-3 h-3 bg-indigo-500 cursor-ne-resize rounded-full shadow-sm" onMouseDown={(e)=>{e.stopPropagation();handleCropStart(e,'resize',crop.id,'tr')}}></div>
                                                <div className="absolute -bottom-1 -left-1 w-3 h-3 bg-indigo-500 cursor-sw-resize rounded-full shadow-sm" onMouseDown={(e)=>{e.stopPropagation();handleCropStart(e,'resize',crop.id,'bl')}}></div>
                                                <div className="absolute -bottom-1 -right-1 w-3 h-3 bg-indigo-500 cursor-se-resize rounded-full shadow-sm" onMouseDown={(e)=>{e.stopPropagation();handleCropStart(e,'resize',crop.id,'br')}}></div>
                                            </div>
                                        )}

                                        <div className={`absolute top-0 left-0 text-white text-[9px] px-1 font-bold ${activeCropId===crop.id ? 'bg-indigo-600' : 'bg-emerald-500'}`}>#{idx+1}</div>
                                        <button className="absolute -top-2 -right-2 w-5 h-5 bg-red-500 text-white rounded-full flex items-center justify-center shadow hover:bg-red-600 z-50" onClick={(e)=>{e.stopPropagation();setCropRegions(p=>p.filter(r=>r.id!==crop.id))}}><i className="fa-solid fa-times text-[10px]"></i></button>
                                    </div>
                                ))}

                                {/* Render Drawing Rectangle with Mask */}
                                {isDrawing && currentRect && (
                                    <div className="absolute border-2 border-dashed border-indigo-500 z-40 pointer-events-none" 
                                         style={{left:`${currentRect.x}%`, top:`${currentRect.y}%`, width:`${currentRect.w}%`, height:`${currentRect.h}%`, boxShadow: '0 0 0 9999px rgba(0, 0, 0, 0.5)'}}>
                                    </div>
                                )}
                            </div>
                        </div>
                   </div>
               </div>
            )}

            {/* Split View: Detail */}
            {formData ? (
                <div className="h-full flex flex-col md:flex-row bg-slate-50">
                    {/* Left Pane: Pan & Zoom Image Viewer */}
                    <div className="md:w-[35%] lg:w-[30%] h-[35vh] md:h-full bg-slate-900 relative flex flex-col overflow-hidden group shrink-0 border-r border-slate-200">
                       {formData.imageUrl ? (
                           <PanZoomImage src={formData.imageUrl} />
                       ) : (
                           <div className="w-full h-full flex flex-col items-center justify-center text-slate-500">
                               <i className="fa-regular fa-image text-4xl mb-2 opacity-50"></i>
                               <span className="text-xs font-medium">無影像資料</span>
                               <span className="text-[10px] opacity-60">(來自 Excel 匯入)</span>
                           </div>
                       )}
                    </div>

                    {/* Right Pane: Editable Data Form */}
                    <div className="flex-1 h-full overflow-y-auto custom-scrollbar bg-white p-4 lg:p-6">
                        <div className="max-w-6xl mx-auto">

                            <div className="grid grid-cols-12 gap-x-4 gap-y-3 items-start">
                                {/* Row 0: Category Switcher */}
                                <div className="col-span-12 mb-2">
                                    <div className="bg-slate-50 p-3 rounded-lg border border-slate-200">
                                        <div className="flex items-center justify-between mb-2">
                                            <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1.5">
                                                <i className="fa-solid fa-layer-group text-indigo-400"></i> Classification (資料分類)
                                            </label>
                                            <span className={`text-[10px] font-bold px-2 py-0.5 rounded uppercase ${
                                                formData.category === 'academic' ? 'bg-amber-100 text-amber-600' :
                                                formData.category === 'staff' ? 'bg-emerald-100 text-emerald-600' :
                                                'bg-blue-100 text-blue-600'
                                            }`}>
                                                Current: {formData.category}
                                            </span>
                                        </div>
                                        <div className="flex bg-slate-200/50 p-1 rounded-lg">
                                            {(['employer', 'academic', 'staff'] as const).map(cat => (
                                                <button
                                                    key={cat}
                                                    onClick={() => updateField('category', cat)}
                                                    className={`flex-1 py-2 rounded-md text-xs font-bold uppercase transition-all flex items-center justify-center gap-2 ${
                                                        formData.category === cat
                                                            ? 'bg-white text-indigo-600 shadow-sm ring-1 ring-black/5'
                                                            : 'text-slate-400 hover:text-slate-600 hover:bg-slate-200/50'
                                                    }`}
                                                >
                                                    <i className={`fa-solid ${
                                                        cat === 'employer' ? 'fa-briefcase' :
                                                        cat === 'academic' ? 'fa-graduation-cap' :
                                                        'fa-user-tag'
                                                    }`}></i>
                                                    {cat}
                                                </button>
                                            ))}
                                        </div>
                                    </div>
                                </div>

                                {/* Row 1: Identity */}
                                <div className="col-span-12 md:col-span-3">
                                    <EditableField label="Prefix (稱謂)" value={formData.prefix} onChange={v => updateField('prefix', v)} icon="fa-user-tag" />
                                </div>
                                <div className="col-span-12 md:col-span-4">
                                    <EditableField label="Last Name (姓氏)" value={formData.lastName} onChange={v => updateField('lastName', v)} />
                                </div>
                                <div className="col-span-12 md:col-span-5">
                                    <EditableField label="First Name (名字)" value={formData.firstName} onChange={v => updateField('firstName', v)} />
                                </div>

                                {/* Row 2: Professional */}
                                <div className="col-span-12 md:col-span-6">
                                    <EditableField label="Job Title / Position (職稱)" value={formData.title} translation={formData.translations?.title} onChange={v => updateField('title', v)} icon="fa-id-badge" />
                                </div>
                                <div className="col-span-12 md:col-span-6">
                                    <EditableField label="Company / Institution (公司/機構)" value={formData.company} translation={formData.translations?.company} onChange={v => updateField('company', v)} icon="fa-building" />
                                </div>

                                {/* Row 3: Org Details */}
                                <div className="col-span-12 md:col-span-4">
                                    <EditableField label="Department (部門)" value={formData.department} translation={formData.translations?.department} onChange={v => updateField('department', v)} />
                                </div>
                                <div className="col-span-12 md:col-span-4">
                                    <EditableField label="Industry (產業)" value={formData.industry} translation={formData.translations?.industry} onChange={v => updateField('industry', v)} />
                                </div>
                                <div className="col-span-12 md:col-span-4">
                                    {formData.category === 'academic' ? (
                                        <EditableField label="Subject (學科)" value={formData.subject} translation={formData.translations?.subject} onChange={v => updateField('subject', v)} icon="fa-book" className="bg-amber-50/50 rounded" />
                                    ) : (
                                        <EditableField label="Country (國家)" value={formData.country} translation={formData.translations?.country} onChange={v => updateField('country', v)} icon="fa-flag" />
                                    )}
                                </div>

                                {/* Row 4: Contact */}
                                <div className="col-span-12 md:col-span-6">
                                    <EditableField label="Email" value={formData.email} onChange={v => updateField('email', v)} icon="fa-envelope" />
                                </div>
                                <div className="col-span-12 md:col-span-6">
                                    <EditableField label="Phone" value={formData.phone} onChange={v => updateField('phone', v)} icon="fa-phone" />
                                </div>

                                {/* Row 5: Contact Cont. */}
                                <div className="col-span-12 md:col-span-6">
                                    <EditableField label="Website" value={formData.website} onChange={v => updateField('website', v)} icon="fa-globe" />
                                </div>
                                <div className="col-span-12 md:col-span-6">
                                    {formData.category === 'academic' && <EditableField label="Country (國家)" value={formData.country} translation={formData.translations?.country} onChange={v => updateField('country', v)} icon="fa-flag" />}
                                </div>

                                {/* Row 6: Address (Full Width) */}
                                <div className="col-span-12">
                                    <EditableField label="Address" value={formData.address} onChange={v => updateField('address', v)} icon="fa-location-dot" />
                                </div>

                                {/* Row 7: Reasoning & Notes (Compact Side-by-Side) */}
                                <div className="col-span-12 md:col-span-6 bg-indigo-50/50 p-3 rounded-lg border border-indigo-100">
                                    <h4 className="text-[10px] font-bold text-indigo-500 uppercase tracking-widest mb-1 flex items-center gap-2">
                                        <i className="fa-solid fa-wand-magic-sparkles"></i> AI Reasoning
                                    </h4>
                                    <p className="text-[10px] text-slate-600 leading-tight font-medium h-12 overflow-y-auto whitespace-pre-line">{formData.reasoning}</p>
                                </div>
                                <div className="col-span-12 md:col-span-6">
                                    <EditableField label="Notes" value={formData.notes} onChange={v => updateField('notes', v)} icon="fa-sticky-note" isTextArea className="h-full" />
                                </div>
                            </div>

                        </div>
                    </div>
                </div>
            ) : (
                /* Empty State */
                <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-400 bg-slate-50/50 p-6">
                    <div className="w-24 h-24 bg-white rounded-[2rem] shadow-xl shadow-indigo-100 flex items-center justify-center mb-6 animate-float">
                        <i className="fa-solid fa-cloud-arrow-up text-4xl text-indigo-500"></i>
                    </div>
                    <h2 className="text-2xl font-bold text-slate-800 mb-2">準備開始工作</h2>
                    <p className="max-w-md text-center text-slate-500 mb-6 leading-relaxed">
                        請從左側列表選擇名片，或是拖曳檔案以開始：
                    </p>
                    <div className="flex gap-4 text-xs font-medium text-slate-500">
                        <div className="bg-white border border-slate-200 px-4 py-2 rounded-lg shadow-sm flex items-center gap-2">
                            <i className="fa-regular fa-image text-indigo-500"></i>
                            <span>名片掃描 (JPG, PNG, PDF)</span>
                        </div>
                        <div className="bg-white border border-slate-200 px-4 py-2 rounded-lg shadow-sm flex items-center gap-2">
                            <i className="fa-solid fa-rotate text-emerald-500"></i>
                            <span>資料還原 (JSON)</span>
                        </div>
                    </div>
                    <p className="mt-4 text-[10px] text-red-400 bg-red-50 px-3 py-1 rounded">注意：系統不支援 Excel 備份還原</p>
                </div>
            )}
         </div>
      </main>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #94a3b8; }
        @keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }
        .animate-float { animation: float 4s ease-in-out infinite; }
        .animate-fadeIn { animation: fadeIn 0.3s ease-out forwards; }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        @keyframes scan { 
          0% { left: -50%; }
          100% { left: 150%; }
        }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { BusinessCardData } from '../types';

interface SearchPageProps {
  cards: BusinessCardData[];
  onSelectCard: (id: string) => void;
  onBack: () => void;
}

type SortOption = 'name_asc' | 'name_desc' | 'company_asc' | 'date_desc' | 'date_asc';
type ViewType = 'grid' | 'list';

const SearchPage: React.FC<SearchPageProps> = ({ cards, onSelectCard, onBack }) => {
  const [query, setQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('name_asc');
  const [viewType, setViewType] = useState<ViewType>('list');
  const [isGrouped, setIsGrouped] = useState(true);

  // Quick Filters
  const [filterHasEmail, setFilterHasEmail] = useState(false);
  const [filterHasPhone, setFilterHasPhone] = useState(false);
  const [filterCategory, setFilterCategory] = useState<'all' | 'employer' | 'academic' | 'staff'>('all');

  // --- Logic ---

  // 1. Filtering
  const filteredCards = useMemo(() => {
    return cards.filter(c => {
      // Text Search
      const q = query.toLowerCase().trim();
      const matchText = !q || (
        (c.firstName?.toLowerCase().includes(q)) ||
        (c.lastName?.toLowerCase().includes(q)) ||
        (c.company?.toLowerCase().includes(q)) ||
        (c.email?.toLowerCase().includes(q)) ||
        (c.phone?.toLowerCase().includes(q)) ||
        (c.title?.toLowerCase().includes(q))
      );

      // Quick Filters
      const matchEmail = !filterHasEmail || !!c.email;
      const matchPhone = !filterHasPhone || !!c.phone;
      const matchCat = filterCategory === 'all' || c.category === filterCategory;

      return matchText && matchEmail && matchPhone && matchCat;
    });
  }, [cards, query, filterHasEmail, filterHasPhone, filterCategory]);

  // 2. Sorting
  const sortedCards = useMemo(() => {
    return [...filteredCards].sort((a, b) => {
      switch (sortBy) {
        case 'name_asc':
          return (a.lastName + a.firstName).localeCompare(b.lastName + b.firstName, 'zh-Hant');
        case 'name_desc':
          return (b.lastName + b.firstName).localeCompare(a.lastName + a.firstName, 'zh-Hant');
        case 'company_asc':
          return (a.company || '').localeCompare(b.company || '', 'zh-Hant');
        case 'date_desc':
          return b.scannedAt - a.scannedAt;
        case 'date_asc':
          return a.scannedAt - b.scannedAt;
        default:
          return 0;
      }
    });
  }, [filteredCards, sortBy]);

  // 3. Grouping (A-Z)
  const groupedCards = useMemo(() => {
    if (!isGrouped || sortBy.includes('date')) return { 'All': sortedCards };

    const groups: Record<string, BusinessCardData[]> = {};

    sortedCards.forEach(card => {
      const keyChar = (sortBy.includes('company') ? card.company : card.lastName)?.charAt(0)?.toUpperCase() || '#';
      // Simple check if it's English alphabet
      let groupKey = /[A-Z]/.test(keyChar) ? keyChar : '# (Other/中文)';

      if (!groups[groupKey]) groups[groupKey] = [];
      groups[groupKey].push(card);
    });

    // Sort keys: A-Z first, then others
    const sortedKeys = Object.keys(groups).sort((a, b) => {
       if (a.startsWith('#') && !b.startsWith('#')) return 1;
       if (!a.startsWith('#') && b.startsWith('#')) return -1;
       return a.localeCompare(b);
    });

    const sortedGroups: Record<string, BusinessCardData[]> = {};
    sortedKeys.forEach(k => sortedGroups[k] = groups[k]);
    return sortedGroups;
  }, [sortedCards, isGrouped, sortBy]);

  // --- Render Helpers ---

  const HighlightText: React.FC<{ text?: string, highlight: string }> = ({ text, highlight }) => {
    if (!text) return null;
    if (!highlight) return <>{text}</>;

    const parts = text.split(new RegExp(`(${highlight})`, 'gi'));
    return (
      <span>
        {parts.map((part, i) => 
          part.toLowerCase() === highlight.toLowerCase() ? <span key={i} className="bg-yellow-200 text-slate-900">{part}</span> : part
        )}
      </span>
    );
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 w-full animate-fadeIn">
      {/* 1. Header & Controls */}
      <div className="bg-white border-b border-slate-200 px-6 py-4 flex flex-col gap-4 shrink-0 shadow-sm z-20">
          <div className="flex items-center gap-4">
              <button onClick={onBack} className="w-9 h-9 flex items-center justify-center rounded-lg hover:bg-slate-100 text-slate-500 transition-colors">
                  <i className="fa-solid fa-arrow-left"></i>
              </button>
              <h2 className="text-xl font-black text-slate-800 tracking-tight">名片資料庫</h2>
              <div className="ml-auto flex items-center bg-slate-100 rounded-lg p-1">
                  <button onClick={() => setViewType('list')} className={`w-8 h-8 rounded-md flex items-center justify-center text-xs transition-all ${viewType === 'list' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>
                      <i className="fa-solid fa-list"></i>
                  </button>
                  <button onClick={() => setViewType('grid')} className={`w-8 h-8 rounded-md flex items-center justify-center text-xs transition-all ${viewType === 'grid' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>
                      <i className="fa-solid fa-grip"></i>
                  </button>
              </div>
          </div>

          <div className="flex flex-col md:flex-row gap-3">
              {/* Search Input */}
              <div className="relative flex-1">
                  <i className="fa-solid fa-search absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"></i>
                  <input 
                      type="text" 
                      className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all font-medium text-slate-700"
                      placeholder="搜尋姓名、公司、電話、Email..."
                      value={query}
                      onChange={e => setQuery(e.target.value)}
                  />
              </div>

              {/* Sort Dropdown */}
              <div className="relative min-w-[160px]">
                  <select 
                      value={sortBy} 
                      onChange={(e) => setSortBy(e.target.value as SortOption)}
                      className="w-full pl-3 pr-8 py-2.5 bg-slate-50 border border-slate-200 rounded-xl appearance-none font-bold text-xs text-slate-600 focus:ring-2 focus:ring-indigo-500/20 outline-none cursor-pointer"
                  >
                      <option value="name_asc">姓名 (A-Z)</option>
                      <option value="name_desc">姓名 (Z-A)</option>
                      <option value="company_asc">公司 (A-Z)</option>
                      <option value="date_desc">掃描日期 (新到舊)</option>
                      <option value="date_asc">掃描日期 (舊到新)</option>
                  </select>
                  <i className="fa-solid fa-sort absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"></i>
              </div>
          </div>

          {/* Filters Chips */}
          <div className="flex flex-wrap gap-2 items-center">
              <button 
                  onClick={() => setIsGrouped(!isGrouped)}
                  className={`px-3 py-1.5 rounded-full text-[10px] font-bold border transition-all flex items-center gap-1.5 ${isGrouped && !sortBy.includes('date') ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-white border-slate-200 text-slate-500 hover:border-indigo-300'}`}
                  disabled={sortBy.includes('date')}
                  title={sortBy.includes('date') ? "日期排序不支援分組" : "依照字母/筆畫分組"}
              >
                  <i className="fa-solid fa-layer-group"></i> 字母分組
              </button>
              <div className="w-px h-4 bg-slate-200 mx-1"></div>

              <button 
                  onClick={() => setFilterHasEmail(!filterHasEmail)}
                  className={`px-3 py-1.5 rounded-full text-[10px] font-bold border transition-all ${filterHasEmail ? 'bg-emerald-50 border-emerald-200 text-emerald-600' : 'bg-white border-slate-200 text-slate-500 hover:border-emerald-300'}`}
              >
                  Has Email
              </button>
              <button 
                  onClick={() => setFilterHasPhone(!filterHasPhone)}
                  className={`px-3 py-1.5 rounded-full text-[10px] font-bold border transition-all ${filterHasPhone ? 'bg-blue-50 border-blue-200 text-blue-600' : 'bg-white border-slate-200 text-slate-500 hover:border-blue-300'}`}
              >
                  Has Phone
              </button>

              <div className="ml-auto flex bg-slate-100 rounded-lg p-0.5">
                  {(['all', 'employer', 'academic', 'staff'] as const).map(cat => (
                      <button 
                          key={cat} 
                          onClick={() => setFilterCategory(cat)} 
                          className={`px-3 py-1 rounded-md text-[10px] font-bold uppercase transition-all ${filterCategory === cat ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                      >
                          {cat}
                      </button>
                  ))}
              </div>
          </div>
      </div>

      {/* 2. Content List */}
      <div className="flex-1 overflow-y-auto p-4 md:p-6 custom-scrollbar">
          {filteredCards.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-slate-400">
                  <i className="fa-solid fa-filter-circle-xmark text-4xl mb-4 opacity-50"></i>
                  <p>沒有找到符合條件的名片</p>
                  <button onClick={() => { setQuery(''); setFilterHasEmail(false); setFilterHasPhone(false); setFilterCategory('all'); }} className="mt-4 text-indigo-600 text-xs font-bold hover:underline">
                      清除所有篩選
                  </button>
              </div>
          ) : (
              <div className="space-y-8 pb-10">
                  {Object.entries(groupedCards).map(([groupTitle, groupItems]) => (
                      <div key={groupTitle}>
                          {/* Group Header */}
                          {(isGrouped && !sortBy.includes('date')) && (
                              <div className="flex items-center gap-4 mb-4">
                                  <div className="w-8 h-8 rounded-lg bg-indigo-600 text-white flex items-center justify-center font-black text-sm shadow-md shadow-indigo-200">
                                      {groupTitle}
                                  </div>
                                  <div className="h-px bg-slate-200 flex-1"></div>
                                  <span className="text-[10px] font-bold text-slate-400">{groupItems.length} 筆</span>
                              </div>
                          )}

                          {/* List Mode */}
                          {viewType === 'list' && (
                              <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
                                  <table className="w-full text-left">
                                      <thead className="bg-slate-50 border-b border-slate-100">
                                          <tr>
                                              <th className="px-4 py-3 text-[10px] font-bold text-slate-400 uppercase tracking-wider w-12"></th>
                                              <th className="px-4 py-3 text-[10px] font-bold text-slate-400 uppercase tracking-wider">Name</th>
                                              <th className="px-4 py-3 text-[10px] font-bold text-slate-400 uppercase tracking-wider">Company / Title</th>
                                              <th className="px-4 py-3 text-[10px] font-bold text-slate-400 uppercase tracking-wider hidden md:table-cell">Contact</th>
                                              <th className="px-4 py-3 text-[10px] font-bold text-slate-400 uppercase tracking-wider w-20 text-right">Action</th>
                                          </tr>
                                      </thead>
                                      <tbody className="divide-y divide-slate-100">
                                          {groupItems.map(card => (
                                              <tr key={card.id} onClick={() => onSelectCard(card.id)} className="group hover:bg-indigo-50/50 cursor-pointer transition-colors">
                                                  <td className="px-4 py-3">
                                                      <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold text-white shadow-sm ${
                                                          card.category === 'academic' ? 'bg-amber-400' :
                                                          card.category === 'staff' ? 'bg-emerald-400' : 'bg-blue-400'
                                                      }`}>
                                                          {card.lastName.charAt(0)}
                                                      </div>
                                                  </td>
                                                  <td className="px-4 py-3">
                                                      <div className="text-sm font-bold text-slate-800">
                                                          <HighlightText text={card.lastName} highlight={query} /> <HighlightText text={card.firstName} highlight={query} />
                                                      </div>
                                                      <div className="text-[10px] text-slate-500 md:hidden mt-0.5">
