import { BusinessCardData } from '../types';

export type ExportMode = 'employer' | 'academic' | 'staff' | 'other' | 'all_original' | 'all_clean' | 'single' | 'full_backup' | 'json';

// Helper: split string by common separators
const splitValues = (str: string): string[] => {
    if (!str) return [];
    return str.split(/[\/\n,;]+/).map(s => s.trim()).filter(Boolean);
};

// Logic: Pick the first phone number available
const selectSinglePhone = (phoneStr: string): string => {
    const phones = splitValues(phoneStr);
    return phones.length > 0 ? phones[0] : '';
};

// Logic: Pick email based on category
const selectBestEmail = (emailStr: string, category: string): string => {
    const emails = splitValues(emailStr);
    if (emails.length === 0) return '';
    if (emails.length === 1) return emails[0];

    const eduEmail = emails.find(e => e.toLowerCase().includes('.edu'));
    const nonEduEmail = emails.find(e => !e.toLowerCase().includes('.edu'));

    if (category === 'academic') {
        // For academic, prefer .edu
        return eduEmail || emails[0];
    } else {
        // For employer/staff/other, prefer non .edu (business email)
        return nonEduEmail || emails[0];
    }
};

export const createExcelFile = async (dataToExport: BusinessCardData[], mode: ExportMode): Promise<File> => {
    const XLSX = await import('xlsx');
    let exportData: any[] = [];

    // Helper to format date
    const formatDate = (ts: number) => new Date(ts).toLocaleString();

    // Map data based on Mode
    if (mode === 'single') {
        exportData = dataToExport.map(c => ({
            'First Name': c.firstName, 'Last Name': c.lastName, 'Title': c.title, 'Title (Trans)': c.translations?.title || '',
            'Company': c.company, 'Company (Trans)': c.translations?.company || '', 'Department': c.department, 'Department (Trans)': c.translations?.department || '',
            'Industry': c.industry, 'Email': c.email, 'Phone': c.phone, 'Website': c.website, 'Address': c.address, 'Country': c.country,
            'Subject': c.subject, 'Category': c.category === 'other' ? 'Not QS' : c.category, 'Reasoning': c.reasoning, 'Notes': c.notes || '', 'Scan Date': formatDate(c.scannedAt), 'Source': c.source
        }));
    } else if (mode === 'full_backup') {
        // Full Backup includes Image Base64 for restoration and ALL data
        exportData = dataToExport.map(c => ({
            'SYSTEM_ID': c.id, 'scannedAt': c.scannedAt, 'category': c.category, 'source': c.source,
            'firstName': c.firstName, 'lastName': c.lastName, 'prefix': c.prefix, 'title': c.title, 'company': c.company,
            'department': c.department, 'industry': c.industry, 'country': c.country, 
            'email': c.email, // Keep original full string
            'phone': c.phone, // Keep original full string
            'subject': c.subject, 'website': c.website, 'address': c.address, 'reasoning': c.reasoning,
            'notes': c.notes || '',
            'trans_title': c.translations?.title || '', 'trans_company': c.translations?.company || '', 'trans_dept': c.translations?.department || '',
            'trans_ind': c.translations?.industry || '', 'trans_subj': c.translations?.subject || '', 'trans_ctry': c.translations?.country || '',
            'IMAGE_BASE64': c.imageUrl 
        }));
    } else if (mode === 'all_clean') {
        exportData = dataToExport.map(c => ({
            'Category': c.category === 'other' ? 'Not QS' : c.category, 'First Name': c.firstName, 'Last Name': c.lastName, 'Title': c.title, 'Company': c.company,
            'Department': c.department, 'Industry': c.industry, 'Subject': c.subject, 'Email': c.email, 'Phone': c.phone,
            'Website': c.website, 'Address': c.address, 'Country': c.country, 'Notes': c.notes || '', 'Scan Date': formatDate(c.scannedAt)
        }));
    } else if (mode === 'all_original') {
        exportData = dataToExport.map(c => ({
             'Category': c.category === 'other' ? 'Not QS' : c.category, 'First Name': c.firstName, 'Last Name': c.lastName,
             'Title (Original)': c.title, 'Title (Note)': c.translations?.title || '',
             'Company (Original)': c.company, 'Company (Note)': c.translations?.company || '',
             'Department (Original)': c.department, 'Department (Note)': c.translations?.department || '',
             'Industry': c.industry, 'Industry (Note)': c.translations?.industry || '',
             'Email': c.email, 'Phone': c.phone, 'Address': c.address, 'Reasoning': c.reasoning, 'Notes': c.notes || ''
        }));
    } else if (mode === 'academic') {
        // STRICT QS ACADEMIC FORMAT (Filtered)
        exportData = dataToExport.map(c => ({
            'Source': c.source || 'QS Hub Scanner',
            'Title': c.prefix || '',
            'First Name': c.firstName || '',
            'Last Name': c.lastName || '',
            'Job Title': c.title || '',
            'Department': c.department || '',
            'Institution': c.company || '',
            'Country or Territory': c.country || '',
            'Email': selectBestEmail(c.email, 'academic'), // Logic: Prefer .edu
            'Subject': c.subject || '',
            'Phone (Optional)': selectSinglePhone(c.phone) // Logic: Pick first
        }));
    } else {
        // STRICT QS EMPLOYER / STAFF FORMAT (Filtered)
        // Also serves as generic export for 'other'
        exportData = dataToExport.map(c => ({
            'Source': c.source || 'QS Hub Scanner',
            'Title': c.prefix || '',
            'First Name': c.firstName || '',
            'Last Name': c.lastName || '',
            'Position': c.title || '',
            'Industry': c.industry || '',
            'Company Name': c.company || '',
            'Country or Territory': c.country || '',
            'Email': selectBestEmail(c.email, c.category), // Logic: Prefer non .edu
            'Phone (Optional)': selectSinglePhone(c.phone) // Logic: Pick first
        }));
    }

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "QS_Export");
    const excelBuffer = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
    const blob = new Blob([excelBuffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const name = mode === 'full_backup' ? `QS_BACKUP_FULL_${new Date().toISOString().split('T')[0]}.xlsx` : `QS_Export_${mode}_${new Date().toISOString().split('T')[0]}.xlsx`;
    return new File([blob], name, { type: blob.type });
};

export const parseExcelImport = async (file: File): Promise<any[]> => {
    const XLSX = await import('xlsx');
    const ab = await file.arrayBuffer();
    const wb = XLSX.read(ab);
    const ws = wb.Sheets[wb.SheetNames[0]];
    return XLSX.utils.sheet_to_json(ws);
};

import React, { useState, useMemo } from 'react';
import { BusinessCardData } from '../types';

interface SearchPageProps {
  cards: BusinessCardData[];
  onSelectCard: (id: string) => void;
  onBack: () => void;
}

type SortOption = 'name_asc' | 'name_desc' | 'company_asc' | 'date_desc' | 'date_asc';
type ViewType = 'grid' | 'list';

const SearchPage: React.FC<SearchPageProps> = ({ cards, onSelectCard, onBack }) => {
  const [query, setQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('name_asc');
  const [viewType, setViewType] = useState<ViewType>('list');
  const [isGrouped, setIsGrouped] = useState(true);

  // Quick Filters
  const [filterHasEmail, setFilterHasEmail] = useState(false);
  const [filterHasPhone, setFilterHasPhone] = useState(false);
  const [filterCategory, setFilterCategory] = useState<'all' | 'employer' | 'academic' | 'staff' | 'other'>('all');

  // --- Logic ---

  // 1. Filtering
  const filteredCards = useMemo(() => {
    return cards.filter(c => {
      // Text Search
      const q = query.toLowerCase().trim();
      const matchText = !q || (
        (c.firstName?.toLowerCase().includes(q)) ||
        (c.lastName?.toLowerCase().includes(q)) ||
        (c.company?.toLowerCase().includes(q)) ||
        (c.email?.toLowerCase().includes(q)) ||
        (c.phone?.toLowerCase().includes(q)) ||
        (c.title?.toLowerCase().includes(q))
      );

      // Quick Filters
      const matchEmail = !filterHasEmail || !!c.email;
      const matchPhone = !filterHasPhone || !!c.phone;
      const matchCat = filterCategory === 'all' || c.category === filterCategory;

      return matchText && matchEmail && matchPhone && matchCat;
    });
  }, [cards, query, filterHasEmail, filterHasPhone, filterCategory]);

  // 2. Sorting
  const sortedCards = useMemo(() => {
    return [...filteredCards].sort((a, b) => {
      switch (sortBy) {
        case 'name_asc':
          return (a.lastName + a.firstName).localeCompare(b.lastName + b.firstName, 'zh-Hant');
        case 'name_desc':
          return (b.lastName + b.firstName).localeCompare(a.lastName + a.firstName, 'zh-Hant');
        case 'company_asc':
          return (a.company || '').localeCompare(b.company || '', 'zh-Hant');
        case 'date_desc':
          return b.scannedAt - a.scannedAt;
        case 'date_asc':
          return a.scannedAt - b.scannedAt;
        default:
          return 0;
      }
    });
  }, [filteredCards, sortBy]);

  // 3. Grouping (A-Z)
  const groupedCards = useMemo(() => {
    if (!isGrouped || sortBy.includes('date')) return { 'All': sortedCards };

    const groups: Record<string, BusinessCardData[]> = {};

    sortedCards.forEach(card => {
      const keyChar = (sortBy.includes('company') ? card.company : card.lastName)?.charAt(0)?.toUpperCase() || '#';
      // Simple check if it's English alphabet
      let groupKey = /[A-Z]/.test(keyChar) ? keyChar : '# (Other/中文)';

      if (!groups[groupKey]) groups[groupKey] = [];
      groups[groupKey].push(card);
    });

    // Sort keys: A-Z first, then others
    const sortedKeys = Object.keys(groups).sort((a, b) => {
       if (a.startsWith('#') && !b.startsWith('#')) return 1;
       if (!a.startsWith('#') && b.startsWith('#')) return -1;
       return a.localeCompare(b);
    });

    const sortedGroups: Record<string, BusinessCardData[]> = {};
    sortedKeys.forEach(k => sortedGroups[k] = groups[k]);
    return sortedGroups;
  }, [sortedCards, isGrouped, sortBy]);

  // --- Render Helpers ---

  const HighlightText: React.FC<{ text?: string, highlight: string }> = ({ text, highlight }) => {
    if (!text) return null;
    if (!highlight) return <>{text}</>;

    const parts = text.split(new RegExp(`(${highlight})`, 'gi'));
    return (
      <span>
        {parts.map((part, i) => 
          part.toLowerCase() === highlight.toLowerCase() ? <span key={i} className="bg-yellow-200 text-slate-900">{part}</span> : part
        )}
      </span>
    );
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 w-full animate-fadeIn">
      {/* 1. Header & Controls */}
      <div className="bg-white border-b border-slate-200 px-6 py-4 flex flex-col gap-4 shrink-0 shadow-sm z-20">
          <div className="flex items-center gap-4">
              <button onClick={onBack} className="w-9 h-9 flex items-center justify-center rounded-lg hover:bg-slate-100 text-slate-500 transition-colors">
                  <i className="fa-solid fa-arrow-left"></i>
              </button>
              <h2 className="text-xl font-black text-slate-800 tracking-tight">名片資料庫</h2>
              <div className="ml-auto flex items-center bg-slate-100 rounded-lg p-1">
                  <button onClick={() => setViewType('list')} className={`w-8 h-8 rounded-md flex items-center justify-center text-xs transition-all ${viewType === 'list' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>
                      <i className="fa-solid fa-list"></i>
                  </button>
                  <button onClick={() => setViewType('grid')} className={`w-8 h-8 rounded-md flex items-center justify-center text-xs transition-all ${viewType === 'grid' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>
                      <i className="fa-solid fa-grip"></i>
                  </button>
              </div>
          </div>

          <div className="flex flex-col md:flex-row gap-3">
              {/* Search Input */}
              <div className="relative flex-1">
                  <i className="fa-solid fa-search absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"></i>
                  <input 
                      type="text" 
                      className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all font-medium text-slate-700"
                      placeholder="搜尋姓名、公司、電話、Email..."
                      value={query}
                      onChange={e => setQuery(e.target.value)}
                  />
              </div>

              {/* Sort Dropdown */}
              <div className="relative min-w-[160px]">
                  <select 
                      value={sortBy} 
                      onChange={(e) => setSortBy(e.target.value as SortOption)}
                      className="w-full pl-3 pr-8 py-2.5 bg-slate-50 border border-slate-200 rounded-xl appearance-none font-bold text-xs text-slate-600 focus:ring-2 focus:ring-indigo-500/20 outline-none cursor-pointer"
                  >
                      <option value="name_asc">姓名 (A-Z)</option>
                      <option value="name_desc">姓名 (Z-A)</option>
                      <option value="company_asc">公司 (A-Z)</option>
                      <option value="date_desc">掃描日期 (新到舊)</option>
                      <option value="date_asc">掃描日期 (舊到新)</option>
                  </select>
                  <i className="fa-solid fa-sort absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"></i>
              </div>
          </div>

          {/* Filters Chips */}
          <div className="flex flex-wrap gap-2 items-center">
              <button 
                  onClick={() => setIsGrouped(!isGrouped)}
                  className={`px-3 py-1.5 rounded-full text-[10px] font-bold border transition-all flex items-center gap-1.5 ${isGrouped && !sortBy.includes('date') ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-white border-slate-200 text-slate-500 hover:border-indigo-300'}`}
                  disabled={sortBy.includes('date')}
                  title={sortBy.includes('date') ? "日期排序不支援分組" : "依照字母/筆畫分組"}
              >
                  <i className="fa-solid fa-layer-group"></i> 字母分組
              </button>
              <div className="w-px h-4 bg-slate-200 mx-1"></div>

              <button 
                  onClick={() => setFilterHasEmail(!filterHasEmail)}
                  className={`px-3 py-1.5 rounded-full text-[10px] font-bold border transition-all ${filterHasEmail ? 'bg-emerald-50 border-emerald-200 text-emerald-600' : 'bg-white border-slate-200 text-slate-500 hover:border-emerald-300'}`}
              >
                  Has Email
              </button>
              <button 
                  onClick={() => setFilterHasPhone(!filterHasPhone)}
                  className={`px-3 py-1.5 rounded-full text-[10px] font-bold border transition-all ${filterHasPhone ? 'bg-blue-50 border-blue-200 text-blue-600' : 'bg-white border-slate-200 text-slate-500 hover:border-blue-300'}`}
              >
                  Has Phone
              </button>

              <div className="ml-auto flex bg-slate-100 rounded-lg p-0.5">
                  {(['all', 'employer', 'academic', 'staff', 'other'] as const).map(cat => (
                      <button 
