import { GoogleGenAI, Type } from "@google/genai";

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const cleanJsonText = (text: string): string => {
  text = text.trim();
  if (text.startsWith('```json')) {
    text = text.replace(/^```json\s*/, '').replace(/\s*```$/, '');
  } else if (text.startsWith('```')) {
    text = text.replace(/^```\s*/, '').replace(/\s*```$/, '');
  }
  return text;
};

/**
 * 通用 API 請求執行器，包含 Auth/Quota Fallback 機制
 */
const executeWithFallback = async <T>(
  operation: (ai: GoogleGenAI) => Promise<T>
): Promise<T> => {
  // 1. 嘗試使用當前的 Key (可能是免費/預設 Key)
  let ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    return await operation(ai);
  } catch (error: any) {
    const errorMessage = (error?.message || JSON.stringify(error)).toLowerCase();

    // 判斷是否為額度不足 (429) 或 權限/金鑰錯誤
    const isQuotaError = errorMessage.includes("429") || errorMessage.includes("resource exhausted") || errorMessage.includes("quota");
    const isAuthError = errorMessage.includes("403") || errorMessage.includes("permission denied") || errorMessage.includes("requested entity was not found") || errorMessage.includes("key");

    // 2. 如果是額度或權限問題，且環境支援切換 Key (window.aistudio)
    if ((isQuotaError || isAuthError) && (window as any).aistudio) {
      console.warn("API Quota/Auth Error. Attempting to switch to Paid/User Key...");

      try {
        // 喚起選擇 Key 的視窗 (使用者選擇付費專案)
        await (window as any).aistudio.openSelectKey();

        // 重要：使用者選完後，process.env.API_KEY 會自動更新
        // 重新初始化 AI 實例以使用新 Key
        ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        // 3. 使用新 Key 重試
        return await operation(ai);
      } catch (fallbackError) {
        console.error("Fallback to paid key failed:", fallbackError);
        throw error; // 如果切換失敗，拋出原始錯誤
      }
    }

    throw error; // 其他錯誤 (如 500) 繼續拋出給外層的 Retry 機制處理
  }
};

/**
 * 提取名片詳細資料 - 使用 Flash 模型以確保極速與精準度
 */
export const extractCardInfo = async (
  base64Image: string, 
  mimeType: string = 'image/jpeg', 
  retryCount = 0
): Promise<any> => {
  const model = 'gemini-3-flash-preview';

  try {
    const response = await executeWithFallback(async (ai) => {
      return await ai.models.generateContent({
        model,
        contents: {
          parts: [
            {
              inlineData: {
                mimeType: mimeType,
                data: base64Image,
              },
            },
            {
              text: `你是一位專業的名片資料分析專家，專門為 QS Hub 系統處理全球名片。

【嚴格規則】：
1. **絕對忠於原圖**：僅提取名片上「肉眼可見」的文字資訊。若名片上沒有該資訊（如電話、地址），請留空，嚴禁自行推測、搜尋或產生不存在的內容。
2. **語言處理 (Language Strategy)**：
   - **英文/中文名片**：若名片包含英文，主要欄位請「優先提取英文」。若僅有中文，則提取中文。
   - **非中英名片 (Other Languages)**：若名片主要語言為**非中文且非英文**的其他外語（例如：日文、韓文、泰文、越南文、德文、法文等），請**直接提取名片上的原文**，不需要翻譯成中文。
3. **翻譯欄位 (Translations)**：保留此物件結構，但若主要欄位已是原文，此處可留空或填入相同的原文，除非你有很高的把握能提供英文翻譯（非強制）。
4. **稱謂 (prefix)**：僅提取名片上明確印出的稱謂 (如 Mr., Ms., Dr., Prof.)。若無，回傳空字串。
5. **店家/通用名片 (Store/General Cards)**：若該圖片是店家、餐廳或企業的通用名片（沒有特定個人的姓名與職稱），請務必將 firstName, lastName, title, prefix **全部留空 ("")**。
6. **分類強制規則 (Category Rule)**：若無法提取出 **lastName (姓氏)**，代表此名片無法歸戶到特定人士，請務必將 category 設定為 **'other'**。

【多重資料提取規則】：
- **電話 (Phone)**：請提取名片上「所有」可見的電話號碼（包含手機、公司電話等），若有多組號碼，請用 " / " 分隔串接在同一個字串中。
- **電子郵件 (Email)**：請提取名片上「所有」可見的電子郵件，若有多組信箱，請用 " / " 分隔串接在同一個字串中。

【AI 摘要 (Reasoning) 規則】：
請用繁體中文撰寫摘要，內容必須包含以下兩點：
1. **人物識別與稱謂建議**：簡介此人是誰（職位/單位）。若名片上沒有 Prefix (稱謂)，請根據其職位或學歷給出建議。若是店家通用名片，請註明「此為店家通用名片」。
2. **分類依據**：說明為什麼將其歸類為 Academic、Employer、Staff 或 Other。
   - **Academic**: 學術界人士 (教授、研究員)。
   - **Employer**: 企業雇主、業界人士。
   - **Staff**: 行政人員。
   - **Other**: **沒有姓氏 (No Last Name)**、不屬於上述 QS 定義的類別、店家通用名片、學生或資訊不足以判斷。

請以 JSON 格式回傳。`,
            },
          ],
        },
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              prefix: { type: Type.STRING },
              firstName: { type: Type.STRING },
              lastName: { type: Type.STRING },
              title: { type: Type.STRING },
              company: { type: Type.STRING },
              department: { type: Type.STRING },
              industry: { type: Type.STRING },
              country: { type: Type.STRING },
              email: { type: Type.STRING },
              subject: { type: Type.STRING },
              phone: { type: Type.STRING },
              website: { type: Type.STRING },
              address: { type: Type.STRING },
              category: { type: Type.STRING, enum: ["employer", "academic", "staff", "other"] },
              reasoning: { type: Type.STRING },
              translations: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  company: { type: Type.STRING },
                  department: { type: Type.STRING },
                  industry: { type: Type.STRING },
                  subject: { type: Type.STRING },
                  country: { type: Type.STRING }
                }
              }
            },
            required: ["firstName", "lastName", "title", "company", "category", "reasoning", "translations"],
          },
        },
      });
    });

    const text = response.text;
    if (!text) throw new Error("AI 回應為空");

    const data = JSON.parse(cleanJsonText(text));

    // ---------------------------------------------------------
    // PHONE NORMALIZATION (電話號碼正規化)
    // 移除橫槓 (-) 與空白，但保留多組號碼的分隔符 (/)
    // ---------------------------------------------------------
    if (data.phone && typeof data.phone === 'string') {
        data.phone = data.phone.split('/')
            .map((p: string) => p.replace(/[-\s]/g, ''))
            .filter((p: string) => p.length > 0)
            .join(' / ');
    }

    // ---------------------------------------------------------
    // HARD RULE CHECK (強制邏輯檢查)
    // 若沒有 Last Name，強制歸類為 'other' (Not QS)
    // ---------------------------------------------------------
    if (!data.lastName || data.lastName.trim() === "") {
        if (data.category !== 'other') {
            data.category = 'other';
            data.reasoning = (data.reasoning || "") + "\n[系統修正]: 由於無法偵測到姓氏，強制歸類為 Other (Not QS)。";
        }
    }

    return data;

  } catch (error: any) {
    let errorMessage = error?.message || "";
    if (!errorMessage) {
        try { errorMessage = JSON.stringify(error); } catch (e) { errorMessage = "Unknown Error"; }
    }

    // Retry on 503 (Service Unavailable), 429 (Rate Limit - if fallback failed), or 500
    if (
        (errorMessage.includes("503") || 
         errorMessage.includes("rate limit") || 
         errorMessage.includes("429") || 
         errorMessage.includes("500") || 
         errorMessage.includes("Internal Server Error")) && 
        retryCount < 3
    ) {
      console.warn(`Gemini API Error (Attempt ${retryCount + 1}):`, errorMessage);
      await sleep(2000 * (retryCount + 1));
      return extractCardInfo(base64Image, mimeType, retryCount + 1);
    }
    throw error;
  }
};

/**
 * AI 自動偵測定位
 */
export const detectBusinessCards = async (base64Image: string, mimeType: string = 'image/jpeg'): Promise<{ymin: number, xmin: number, ymax: number, xmax: number}[]> => {
  try {
    const response = await executeWithFallback(async (ai) => {
        return await ai.models.generateContent({
            model: 'gemini-3-flash-preview', 
            contents: {
              parts: [
                {
                  inlineData: {
                    mimeType: mimeType,
                    data: base64Image,
                  },
                },
                {
                  // Improved prompt for better detection of multiple items and orientation handling
                  text: "Identify the bounding boxes for **each individual business card** in this image. The image may contain multiple cards arranged in a grid. Ignore background noise. Return the result as a JSON object with a 'boxes' array containing [ymin, xmin, ymax, xmax] for each card in normalized coordinates (0-1000).",
                },
              ],
            },
            config: {
              responseMimeType: "application/json",
              responseSchema: {
                type: Type.OBJECT,
                properties: {
                  boxes: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        ymin: { type: Type.NUMBER },
                        xmin: { type: Type.NUMBER },
                        ymax: { type: Type.NUMBER },
                        xmax: { type: Type.NUMBER },
                      },
                      required: ["ymin", "xmin", "ymax", "xmax"]
                    }
                  }
                }
              }
            }
          });
    });

    const text = response.text;
    if (!text) return [];
    const data = JSON.parse(cleanJsonText(text));
    return data.boxes || [];
  } catch (e) {
    console.warn("AI Detection failed:", e);
    return [];
  }
};

import React, { useState, useMemo } from 'react';
import { BusinessCardData } from '../types';

interface SearchPageProps {
  cards: BusinessCardData[];
  onSelectCard: (id: string) => void;
  onBack: () => void;
}

type SortOption = 'name_asc' | 'name_desc' | 'company_asc' | 'date_desc' | 'date_asc';

const SearchPage: React.FC<SearchPageProps> = ({ cards, onSelectCard, onBack }) => {
  const [query, setQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('name_asc');
  const [isGrouped, setIsGrouped] = useState(true);

  // Quick Filters
  const [filterHasEmail, setFilterHasEmail] = useState(false);
  const [filterHasPhone, setFilterHasPhone] = useState(false);
  const [filterCategory, setFilterCategory] = useState<'all' | 'employer' | 'academic' | 'staff' | 'other'>('all');

  // --- Logic ---

  // 1. Filtering
  const filteredCards = useMemo(() => {
    return cards.filter(c => {
      // Text Search
      const q = query.toLowerCase().trim();
      const matchText = !q || (
        (c.firstName?.toLowerCase().includes(q)) ||
        (c.lastName?.toLowerCase().includes(q)) ||
        (c.company?.toLowerCase().includes(q)) ||
        (c.email?.toLowerCase().includes(q)) ||
        (c.phone?.toLowerCase().includes(q)) ||
        (c.title?.toLowerCase().includes(q))
      );

      // Quick Filters
      const matchEmail = !filterHasEmail || !!c.email;
      const matchPhone = !filterHasPhone || !!c.phone;
      const matchCat = filterCategory === 'all' || c.category === filterCategory;

      return matchText && matchEmail && matchPhone && matchCat;
    });
  }, [cards, query, filterHasEmail, filterHasPhone, filterCategory]);

  // 2. Sorting
  const sortedCards = useMemo(() => {
    return [...filteredCards].sort((a, b) => {
      switch (sortBy) {
        case 'name_asc':
          const nameA = (a.firstName || a.lastName) ? (a.lastName + a.firstName) : a.company;
          const nameB = (b.firstName || b.lastName) ? (b.lastName + b.firstName) : b.company;
          return (nameA || '').localeCompare(nameB || '', 'zh-Hant');
        case 'name_desc':
          const nameA_d = (a.firstName || a.lastName) ? (a.lastName + a.firstName) : a.company;
          const nameB_d = (b.firstName || b.lastName) ? (b.lastName + b.firstName) : b.company;
          return (nameB_d || '').localeCompare(nameA_d || '', 'zh-Hant');
        case 'company_asc':
          return (a.company || '').localeCompare(b.company || '', 'zh-Hant');
        case 'date_desc':
          return b.scannedAt - a.scannedAt;
        case 'date_asc':
          return a.scannedAt - b.scannedAt;
        default:
          return 0;
      }
    });
  }, [filteredCards, sortBy]);

  // 3. Grouping (A-Z)
  const groupedCards = useMemo(() => {
    if (!isGrouped || sortBy.includes('date')) return { 'All': sortedCards };

    const groups: Record<string, BusinessCardData[]> = {};

    sortedCards.forEach(card => {
      let keyChar = '';
      if (sortBy.includes('company')) {
          keyChar = card.company?.charAt(0)?.toUpperCase();
      } else {
          // If no last name, use company char
          keyChar = card.lastName ? card.lastName.charAt(0).toUpperCase() : (card.company ? card.company.charAt(0).toUpperCase() : '#');
      }

      // Simple check if it's English alphabet
      let groupKey = /[A-Z]/.test(keyChar) ? keyChar : '# (Other/中文)';

      if (!groups[groupKey]) groups[groupKey] = [];
      groups[groupKey].push(card);
    });

    // Sort keys: A-Z first, then others
    const sortedKeys = Object.keys(groups).sort((a, b) => {
       if (a.startsWith('#') && !b.startsWith('#')) return 1;
       if (!a.startsWith('#') && b.startsWith('#')) return -1;
       return a.localeCompare(b);
    });

    const sortedGroups: Record<string, BusinessCardData[]> = {};
    sortedKeys.forEach(k => sortedGroups[k] = groups[k]);
    return sortedGroups;
  }, [sortedCards, isGrouped, sortBy]);

  // --- Render Helpers ---

  const HighlightText: React.FC<{ text?: string, highlight: string }> = ({ text, highlight }) => {
    if (!text) return null;
    if (!highlight) return <>{text}</>;

    const parts = text.split(new RegExp(`(${highlight})`, 'gi'));
    return (
      <span>
        {parts.map((part, i) => 
          part.toLowerCase() === highlight.toLowerCase() ? <span key={i} className="bg-yellow-200 text-slate-900">{part}</span> : part
        )}
      </span>
    );
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 w-full animate-fadeIn">
      {/* 1. Header & Controls */}
      <div className="bg-white border-b border-slate-200 px-6 py-4 flex flex-col gap-4 shrink-0 shadow-sm z-20">
          <div className="flex items-center gap-4">
              <button onClick={onBack} className="w-9 h-9 flex items-center justify-center rounded-lg hover:bg-slate-100 text-slate-500 transition-colors">
                  <i className="fa-solid fa-arrow-left"></i>
              </button>
              <h2 className="text-xl font-black text-slate-800 tracking-tight">名片資料庫</h2>
          </div>

          <div className="flex flex-col md:flex-row gap-3">
              {/* Search Input */}
              <div className="relative flex-1">
                  <i className="fa-solid fa-search absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"></i>
                  <input 
                      type="text" 
                      className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all font-medium text-slate-700"
                      placeholder="搜尋姓名、公司、電話、Email..."
                      value={query}
                      onChange={e => setQuery(e.target.value)}
                  />
              </div>

              {/* Sort Dropdown */}
              <div className="relative min-w-[160px]">
                  <select 
                      value={sortBy} 
                      onChange={(e) => setSortBy(e.target.value as SortOption)}
                      className="w-full pl-3 pr-8 py-2.5 bg-slate-50 border border-slate-200 rounded-xl appearance-none font-bold text-xs text-slate-600 focus:ring-2 focus:ring-indigo-500/20 outline-none cursor-pointer"
                  >
                      <option value="name_asc">姓名 (A-Z)</option>
                      <option value="name_desc">姓名 (Z-A)</option>
                      <option value="company_asc">公司 (A-Z)</option>
                      <option value="date_desc">掃描日期 (新到舊)</option>
                      <option value="date_asc">掃描日期 (舊到新)</option>
                  </select>
                  <i className="fa-solid fa-sort absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"></i>
              </div>
          </div>

          {/* Filters Chips */}
          <div className="flex flex-wrap gap-2 items-center">
              <button 
                  onClick={() => setIsGrouped(!isGrouped)}
                  className={`px-3 py-1.5 rounded-full text-[10px] font-bold border transition-all flex items-center gap-1.5 ${isGrouped && !sortBy.includes('date') ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-white border-slate-200 text-slate-500 hover:border-indigo-300'}`}
                  disabled={sortBy.includes('date')}
                  title={sortBy.includes('date') ? "日期排序不支援分組" : "依照字母/筆畫分組"}
              >
                  <i className="fa-solid fa-layer-group"></i> 字母分組
              </button>
              <div className="w-px h-4 bg-slate-200 mx-1"></div>

              <button 
                  onClick={() => setFilterHasEmail(!filterHasEmail)}
                  className={`px-3 py-1.5 rounded-full text-[10px] font-bold border transition-all ${filterHasEmail ? 'bg-emerald-50 border-emerald-200 text-emerald-600' : 'bg-white border-slate-200 text-slate-500 hover:border-emerald-300'}`}
              >
                  Has Email
              </button>
              <button 
                  onClick={() => setFilterHasPhone(!filterHasPhone)}
                  className={`px-3 py-1.5 rounded-full text-[10px] font-bold border transition-all ${filterHasPhone ? 'bg-blue-50 border-blue-200 text-blue-600' : 'bg-white border-slate-200 text-slate-500 hover:border-blue-300'}`}
              >
                  Has Phone
              </button>

              <div className="ml-auto flex bg-slate-100 rounded-lg p-0.5">
                  {(['all', 'employer', 'academic', 'staff', 'other'] as const).map(cat => (
                      <button 
                          key={cat} 
                          onClick={() => setFilterCategory(cat)} 
                          className={`px-3 py-1 rounded-md text-[10px] font-bold uppercase transition-all ${filterCategory === cat ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                      >
                          {cat === 'other' ? 'Not QS' : cat}
                      </button>
                  ))}
              </div>
          </div>
      </div>

      {/* 2. Content List */}
      <div className="flex-1 overflow-y-auto p-4 md:p-6 custom-scrollbar">
          {filteredCards.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-slate-400">
                  <i className="fa-solid fa-filter-circle-xmark text-4xl mb-4 opacity-50"></i>
                  <p>沒有找到符合條件的名片</p>
                  <button onClick={() => { setQuery(''); setFilterHasEmail(false); setFilterHasPhone(false); setFilterCategory('all'); }} className="mt-4 text-indigo-600 text-xs font-bold hover:underline">
                      清除所有篩選
                  </button>
              </div>
          ) : (
              <div className="space-y-8 pb-10">
                  {Object.entries(groupedCards).map(([groupTitle, groupItems]) => (
                      <div key={groupTitle}>
                          {/* Group Header */}
                          {(isGrouped && !sortBy.includes('date')) && (
                              <div className="flex items-center gap-4 mb-4">
                                  <div className="w-8 h-8 rounded-lg bg-indigo-600 text-white flex items-center justify-center font-black text-sm shadow-md shadow-indigo-200">
                                      {groupTitle}
                                  </div>
                                  <div className="h-px bg-slate-200 flex-1"></div>
                                  <span className="text-[10px] font-bold text-slate-400">{groupItems.length} 筆</span>
                              </div>
                          )}

                          {/* List View Only */}
                          <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
                              <table className="w-full text-left">
                                  <thead className="bg-slate-50 border-b border-slate-100">
