                                                  {card.phone && <div className="text-[10px] text-slate-600 flex items-center gap-1 mt-0.5"><i className="fa-solid fa-phone text-slate-400"></i> <HighlightText text={card.phone.split('/')[0]} highlight={query} /></div>}
