// Helper to find object value by case-insensitive key
const getValue = (row: any, keys: string[]): string | undefined => {
    const rowKeys = Object.keys(row);
    for (const k of keys) {
        const match = rowKeys.find(rk => rk.toLowerCase() === k.toLowerCase());
        if (match && row[match]) return String(row[match]).trim();
    }
    return undefined;
};

// --- Tour Component ---
interface TourStep {
    targetId: string;
    title: string;
    content: string;
    position: 'right' | 'bottom' | 'bottom-left' | 'bottom-right' | 'top' | 'left';
}

const TourOverlay: React.FC<{ 
    stepIndex: number; 
    steps: TourStep[]; 
    onNext: () => void; 
    onSkip: () => void; 
}> = ({ stepIndex, steps, onNext, onSkip }) => {
    const [targetRect, setTargetRect] = useState<DOMRect | null>(null);
    const currentStep = steps[stepIndex];

    useEffect(() => {
        const updateRect = () => {
            const el = document.getElementById(currentStep.targetId);
            if (el) {
                setTargetRect(el.getBoundingClientRect());
                // Scroll into view if needed
                el.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        };
        updateRect();
        window.addEventListener('resize', updateRect);
        // Add a small delay to allow UI to settle (especially when viewMode changes)
        const timer = setTimeout(updateRect, 300);
        return () => {
            window.removeEventListener('resize', updateRect);
            clearTimeout(timer);
        };
    }, [stepIndex, currentStep.targetId]);

    if (!targetRect) return null;

    // Calculate position for the tooltip
    let tooltipStyle: React.CSSProperties = {};
    const gap = 20;

    // Default fallback to center if calculation fails
    let top = window.innerHeight / 2;
    let left = window.innerWidth / 2;

    switch (currentStep.position) {
        case 'right':
            top = targetRect.top;
            left = targetRect.right + gap;
            break;
        case 'left':
            top = targetRect.top;
            left = targetRect.left - 320 - gap; // Approx width of card
            break;
        case 'bottom':
            top = targetRect.bottom + gap;
            left = targetRect.left + (targetRect.width / 2) - 160;
            break;
        case 'bottom-left':
            top = targetRect.bottom + gap;
            left = targetRect.left;
            break;
        case 'bottom-right':
            top = targetRect.bottom + gap;
            left = targetRect.right - 320;
            break;
        case 'top':
            top = targetRect.top - 200; // Approx height
            left = targetRect.left + (targetRect.width / 2) - 160;
            break;
    }

    // Boundary checks to keep tooltip on screen
    if (left < 10) left = 10;
    if (left + 320 > window.innerWidth) left = window.innerWidth - 330;
    if (top < 10) top = 10;
    if (top + 150 > window.innerHeight) top = window.innerHeight - 160;

    tooltipStyle = { top, left };

    return (
        <div className="fixed inset-0 z-[9999] overflow-hidden">
            {/* Cutout Mask using SVG */}
            <svg className="absolute inset-0 w-full h-full pointer-events-none transition-all duration-500">
                <defs>
                    <mask id="tour-mask">
                        <rect x="0" y="0" width="100%" height="100%" fill="white" />
                        <rect 
                            x={targetRect.left - 8} 
                            y={targetRect.top - 8} 
                            width={targetRect.width + 16} 
                            height={targetRect.height + 16} 
                            rx="12" 
                            fill="black" 
                        />
                    </mask>
                </defs>
                <rect x="0" y="0" width="100%" height="100%" fill="rgba(0,0,0,0.6)" mask="url(#tour-mask)" />
            </svg>

            {/* Pulsing Border & Glow around target */}
            <div 
                className="absolute rounded-xl pointer-events-none transition-all duration-300 border-4 border-indigo-400/80 shadow-[0_0_30px_rgba(99,102,241,0.6)] animate-pulse"
                style={{
                    top: targetRect.top - 8,
                    left: targetRect.left - 8,
                    width: targetRect.width + 16,
                    height: targetRect.height + 16
                }}
            >
                {/* Cute Floating Hand Pointer */}
                <div className="absolute -bottom-14 -right-12 text-5xl animate-[bounce_1.5s_infinite]">
                    👉
                </div>
            </div>

            {/* Tooltip Card */}
            <div 
                className="absolute bg-white p-6 rounded-2xl shadow-2xl w-80 animate-[float_3s_ease-in-out_infinite] border-2 border-indigo-100 flex flex-col gap-4"
                style={tooltipStyle}
            >
                <div className="flex items-start gap-3">
                    <div className="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-xl shrink-0">
                        {stepIndex === 0 ? '👋' : stepIndex === steps.length - 1 ? '🎉' : '💡'}
                    </div>
                    <div>
                        <h3 className="text-base font-bold text-slate-800 mb-1.5">{currentStep.title}</h3>
                        <p className="text-sm text-slate-500 leading-relaxed">{currentStep.content}</p>
                    </div>
                </div>

                {/* Progress Dots */}
                <div className="flex items-center justify-center gap-1.5 my-1">
                    {steps.map((_, i) => (
                        <div key={i} className={`h-1.5 rounded-full transition-all ${i === stepIndex ? 'w-6 bg-indigo-500' : 'w-1.5 bg-slate-200'}`}></div>
                    ))}
                </div>

                <div className="flex items-center justify-between pt-2 border-t border-slate-100">
                    <button onClick={onSkip} className="text-xs font-bold text-slate-400 hover:text-slate-600 px-2 py-1">跳過教學</button>
                    <button 
                        onClick={onNext} 
                        className="bg-indigo-600 text-white px-5 py-2 rounded-xl text-sm font-bold shadow-lg shadow-indigo-200 hover:bg-indigo-700 active:scale-95 transition-all flex items-center gap-2 group"
                    >
                        {stepIndex === steps.length - 1 ? '開始使用！' : '下一步'} 
                        <i className="fa-solid fa-arrow-right group-hover:translate-x-1 transition-transform"></i>
                    </button>
                </div>
            </div>
        </div>
    );
};

