                            </div>
                            <div className="flex-1 min-w-0">
                                {/* Name: If no name, show company name as main text */}
                                <div className="text-sm md:text-base font-bold text-slate-800 truncate">
                                    {(c.firstName || c.lastName) ? `${c.firstName} ${c.lastName}` : (c.company || '未知名片')}
                                </div>
                                {/* Subtitle: If no name, show title/category or "General Card" */}
                                <div className="text-xs font-medium text-slate-400 uppercase tracking-wide truncate">
                                    {(c.firstName || c.lastName) ? c.company : (c.category === 'other' ? 'General Card (Not QS)' : c.category)}
                                </div>
                            </div>
                            <button onClick={(e) => handleDeleteCard(e, c.id)} className="w-7 h-7 flex items-center justify-center rounded-lg text-slate-300 hover:bg-red-50 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"><i className="fa-solid fa-trash-can text-xs"></i></button>
                        </div>
                    ))
                )}
            </div>
         </div>
      </aside>

