                             <button onClick={handleClearAll} disabled={cards.length === 0} className="h-9 px-3 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors" title="清空全部">
                                 <i className="fa-solid fa-trash-can"></i>
                             </button>
