                       <div className="absolute inset-0 z-40 bg-slate-100 flex flex-col" onMouseMove={handleCropperMouseMove} onMouseUp={handleCropperMouseUp} onTouchMove={handleCropperMouseMove} onTouchEnd={handleCropperMouseUp}>
