  try {
    const response = await executeWithFallback(async (ai) => {
        return await ai.models.generateContent({
            model: 'gemini-3-flash-preview', 
            contents: {
              parts: [
                { inlineData: { mimeType: mimeType, data: base64Image } },
                { text: "Identify bounding boxes for individual business cards. Return JSON {boxes: [{ymin, xmin, ymax, xmax}]}" },
              ],
            },
            config: {
              responseMimeType: "application/json",
              responseSchema: {
                type: Type.OBJECT,
                properties: {
                  boxes: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: { ymin: { type: Type.NUMBER }, xmin: { type: Type.NUMBER }, ymax: { type: Type.NUMBER }, xmax: { type: Type.NUMBER } },
                      required: ["ymin", "xmin", "ymax", "xmax"]
                    }
                  }
                }
              }
            }
          });
    });
    const data = JSON.parse(cleanJsonText(response.text));
    return data.boxes || [];
  } catch (e) {
    return [];
  }
};

