                setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
                // Important: Trigger background summary generation for imported data
                fillMissingSummaries();
            } catch (err) { alert("Restore Failed"); }
        };
        reader.readAsText(files[0]);
        return;
    }

    const newTasks: ProcessingTask[] = [];
    for (const f of Array.from(files) as File[]) {
      if (!f.type.startsWith('image/')) continue;
      const id = crypto.randomUUID();
      filesMap.current.set(id, f);
      newTasks.push({ id, fileName: f.name, status: 'pending', progress: 0, batchIndex: 1, previewUrl: URL.createObjectURL(f) });
    }
    setTasks(prev => [...prev, ...newTasks]);
  };

  return (
