  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);
  const [activeCategory, setActiveCategory] = useState<'employer' | 'academic' | 'staff' | 'other'>('employer');
  const [searchQuery, setSearchQuery] = useState('');
  const [isExporting, setIsExporting] = useState(false);
  const [isQueuePaused, setIsQueuePaused] = useState(false);
  const [isDragOver, setIsDragOver] = useState(false);
  const [showExportMenu, setShowExportMenu] = useState(false);
  const [showSettingsMenu, setShowSettingsMenu] = useState(false);
  const [showMobileUploadHint, setShowMobileUploadHint] = useState(false);
  const [tourStepIndex, setTourStepIndex] = useState<number>(-1);
  const [isSummaryFilling, setIsSummaryFilling] = useState(false);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const tasksRef = useRef<ProcessingTask[]>([]);
  const processingMutex = useRef(false);
  const pausedRef = useRef(false);
  const dragCounter = useRef(0);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const exportMenuRef = useRef<HTMLDivElement>(null);
  const settingsMenuRef = useRef<HTMLDivElement>(null);

  const [cropperImage, setCropperImage] = useState<string | null>(null);
  const [cropRegions, setCropRegions] = useState<CropRegion[]>([]);
  const [activeCropId, setActiveCropId] = useState<string | null>(null);
  const [isAiDetecting, setIsAiDetecting] = useState(false);
  const cropperImgRef = useRef<HTMLImageElement>(null);
  const [cropperTransform, setCropperTransform] = useState({ scale: 1, x: 0, y: 0 });

  const activeTasks = useMemo(() => tasks, [tasks]);
  const visibleCards = useMemo(() => cards.filter(c => c.category === activeCategory), [cards, activeCategory]);

  // Define Tour Steps
  const tourSteps = [
      {
          targetId: 'btn-upload',
          title: '開始第一步',
          content: '點擊此按鈕上傳名片圖片 (支援 JPG, PNG, PDF)，或使用相機拍照。',
          position: isMobile ? 'bottom-left' : 'right'
      },
      {
          targetId: 'btn-search',
          title: '資料庫搜尋',
          content: '點擊這裡進入全螢幕資料庫，您可以進行篩選、排序或搜尋特定名片。',
          position: 'bottom-left'
      },
      {
          targetId: 'detail-panel',
          title: '名片詳情與 AI 分析',
          content: '當您選擇名片後，這裡會顯示完整資訊。您可以編輯任何欄位，並查看 AI 提供的分類理由摘要。',
          position: 'left'
      },
      {
          targetId: 'btn-export',
          title: '匯出資料',
          content: '這裡可以將掃描好的資料匯出成 QS 格式、Excel 或備份檔。',
          position: 'bottom-right'
      },
      {
          targetId: 'btn-settings',
          title: '系統設定',
          content: '設定 API 金鑰或清除所有資料（危險區域）都在這裡。',
          position: 'bottom-right'
      }
  ];

  useEffect(() => { tasksRef.current = tasks; }, [tasks]);
  useEffect(() => { pausedRef.current = isQueuePaused; }, [isQueuePaused]);

  // --- Background Summary Filler ---
  const fillMissingSummaries = useCallback(async () => {
      if (isSummaryFilling) return;
      setIsSummaryFilling(true);

      try {
          // Fetch full data for cards without summaries
          const allCardsMeta = await getCardsMetadataFromDB();
          const cardsNeedingSummary = [];

          for (const meta of allCardsMeta) {
              const fullCard = await getCardById(meta.id);
              if (fullCard && (!fullCard.summary || fullCard.summary.trim() === "")) {
                  cardsNeedingSummary.push(fullCard);
              }
          }

          if (cardsNeedingSummary.length > 0) {
              console.log(`Starting background summary generation for ${cardsNeedingSummary.length} cards...`);
              for (const card of cardsNeedingSummary) {
                  const newSummary = await generateMissingSummary(card);
                  if (newSummary) {
                      const updatedCard = { ...card, summary: newSummary };
                      await saveCardToDB(updatedCard);
                      // Update local state UI if it's the current selected one
                      if (selectedCardId === card.id) setFormData(updatedCard);
                  }
                  await new Promise(r => setTimeout(r, 1000)); // Throttle
              }
              // Refresh metadata list
              const freshMeta = await getCardsMetadataFromDB();
              setCards(freshMeta.sort((a, b) => b.scannedAt - a.scannedAt));
          }
      } catch (err) {
          console.error("Background Summary Filler Error:", err);
      } finally {
          setIsSummaryFilling(false);
      }
  }, [isSummaryFilling, selectedCardId]);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener('resize', handleResize);

    getCardsMetadataFromDB().then(savedCards => {
      if (savedCards) setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
      // Background check for missing summaries on start
      fillMissingSummaries();
    });

    const hasVisited = localStorage.getItem('qs_scanner_v1_visited');
    if (!hasVisited) setTimeout(() => setTourStepIndex(0), 1000);

    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    if (selectedCardId) {
      getCardById(selectedCardId).then(data => {
        if (data) { setFormData(data); setIsFormDirty(false); }
      });
    } else {
      setFormData(null); setIsFormDirty(false);
    }
  }, [selectedCardId]);

  const handleSave = async () => {
      if (!formData) return;
      await saveCardToDB(formData);
      setCards(prev => prev.map(c => c.id === formData.id ? { ...c, ...formData } : c));
      setIsFormDirty(false);
  };

  const updateField = (field: keyof BusinessCardData, value: string) => {
      if (!formData) return;
      setFormData({ ...formData, [field]: value });
      setIsFormDirty(true);
  };

  const performSingleTask = async (task: ProcessingTask) => {
    try {
        const fileObj = filesMap.current.get(task.id);
        if (!fileObj) throw new Error("File missing");
        const base64Data = await compressImage(fileObj);
        const info = await extractCardInfo(base64Data, 'image/jpeg');
        const newCard: BusinessCardData = {
            notes: '', prefix: '', fax: '', summary: '', reasoning: '',
            ...info, id: task.id, scannedAt: Date.now(), source: 'QS Hub Scanner',
            imageUrl: `data:image/jpeg;base64,${base64Data}`,
        };
        await saveCardToDB(newCard);
        setCards(prev => [newCard as BusinessCardData, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));
        setTasks(prev => prev.filter(t => t.id !== task.id));
    } catch (err: any) {
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    }
  };

  const processQueue = useCallback(async () => {
    if (processingMutex.current || pausedRef.current) return;
    processingMutex.current = true;
    setIsProcessing(true);
    try {
        while (true) {
            if (pausedRef.current) break;
            const nextTask = tasksRef.current.find(t => t.status === 'pending');
            if (!nextTask) break;
            setTasks(prev => prev.map(t => t.id === nextTask.id ? { ...t, status: 'processing' } : t));
            await performSingleTask(nextTask);
        }
    } finally {
        processingMutex.current = false;
        setIsProcessing(false);
    }
  }, []);

  useEffect(() => { if (!isQueuePaused && !isProcessing) processQueue(); }, [tasks, isQueuePaused, isProcessing, processQueue]);

  const handleShare = async () => {
      if (!formData) return;
      const shareText = 
          `【人物簡介】\n${formData.summary || '此名片摘要生成中...'}\n\n` +
          `姓名: ${formData.lastName}${formData.firstName}\n` +
          `公司: ${formData.company}\n` +
          `職稱: ${formData.title}\n` +
          (formData.phone ? `電話: ${formData.phone}\n` : '') +
          (formData.email ? `信箱: ${formData.email}\n` : '') +
          `\n----------------------------\n` +
          `⚠️ 注意：以上資訊由 AI 輔助生成，僅供商務參考，具體內容請務必再次查證。`;

      if (navigator.share) {
          try { await navigator.share({ title: `${formData.firstName} ${formData.lastName}`, text: shareText }); } 
          catch (err) { console.warn('Share failed', err); }
      } else {
          navigator.clipboard.writeText(shareText);
          alert("已複製到剪貼簿 (含 AI 免責聲明)");
      }
  };

  const processFiles = async (files: FileList | null) => {
    if (!files || files.length === 0) return;

    if (files.length === 1 && files[0].name.toLowerCase().endsWith('.json')) {
        const reader = new FileReader();
        reader.onload = async (e) => {
            try {
                const data = JSON.parse(e.target?.result as string);
                const items = Array.isArray(data) ? data : [data];
                for (const item of items) await saveCardToDB(item as BusinessCardData);
                const savedCards = await getCardsMetadataFromDB();
                setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
                // Important: Trigger background summary generation for imported data
                fillMissingSummaries();
            } catch (err) { alert("Restore Failed"); }
        };
        reader.readAsText(files[0]);
        return;
    }

    const newTasks: ProcessingTask[] = [];
    for (const f of Array.from(files) as File[]) {
      if (!f.type.startsWith('image/')) continue;
      const id = crypto.randomUUID();
      filesMap.current.set(id, f);
      newTasks.push({ id, fileName: f.name, status: 'pending', progress: 0, batchIndex: 1, previewUrl: URL.createObjectURL(f) });
    }
    setTasks(prev => [...prev, ...newTasks]);
  };

  const handleTourNext = () => {
      if (tourStepIndex < tourSteps.length - 1) {
          setTourStepIndex(prev => prev + 1);
      } else {
          setTourStepIndex(-1);
          localStorage.setItem('qs_scanner_v1_visited', 'true');
      }
  };

  const handleTourSkip = () => {
      setTourStepIndex(-1);
      localStorage.setItem('qs_scanner_v1_visited', 'true');
  };

  return (
    <div className="flex h-screen w-full bg-slate-50 text-slate-900 font-sans overflow-hidden" onDrop={(e) => { e.preventDefault(); processFiles(e.dataTransfer.files); setIsDragOver(false); }} onDragOver={(e) => { e.preventDefault(); setIsDragOver(true); }}>
      <input type="file" ref={fileInputRef} className="hidden" accept=".jpg, .jpeg, .png, .pdf, .json" multiple onChange={(e) => processFiles(e.target.files)} />
      {tourStepIndex >= 0 && <TourOverlay stepIndex={tourStepIndex} steps={tourSteps} onNext={handleTourNext} onSkip={handleTourSkip} />}

      <aside className={`${isMobile && viewMode !== 'file' ? 'hidden' : 'flex'} w-full md:w-[320px] lg:w-[380px] flex-row bg-white border-r z-10 shrink-0`}>
         <div className="w-[64px] bg-slate-50 border-r flex flex-col items-center py-4 gap-3 shrink-0">
             <button id="btn-upload" onClick={() => fileInputRef.current?.click()} className="w-10 h-10 rounded-xl bg-indigo-600 text-white shadow-lg flex items-center justify-center"><i className="fa-solid fa-plus text-sm"></i></button>
             <div className="flex-1 w-full overflow-y-auto flex flex-col items-center gap-2">
                 {activeTasks.map(t => (
                     <div key={t.id} className="w-10 h-10 rounded-lg bg-white border border-slate-200 overflow-hidden relative">
                         {t.previewUrl && <img src={t.previewUrl} className="w-full h-full object-cover" />}
                         {t.status === 'processing' && <div className="absolute inset-0 bg-black/40 flex items-center justify-center"><i className="fa-solid fa-circle-notch fa-spin text-white text-[10px]"></i></div>}
                     </div>
                 ))}
             </div>
         </div>
         <div className="flex-1 flex flex-col min-w-0">
            <div className="p-4 border-b">
                <div className="flex items-center justify-between mb-4">
                    <h1 className="text-lg font-black">QS HUB <span className="text-xs text-indigo-500">{isSummaryFilling ? 'Summary Filling...' : ''}</span></h1>
                    <button id="btn-export" onClick={() => setShowExportMenu(!showExportMenu)} className="w-8 h-8 text-slate-400 hover:text-indigo-600"><i className="fa-solid fa-file-export"></i></button>
                </div>
                <div className="flex p-1 bg-slate-100 rounded-lg">
                    {(['employer', 'academic', 'staff', 'other'] as const).map(cat => (
                        <button key={cat} onClick={() => setActiveCategory(cat)} className={`flex-1 py-1 rounded-md text-[10px] font-bold uppercase transition-all ${activeCategory === cat ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-500'}`}>{cat}</button>
                    ))}
                </div>
            </div>
            <div className="flex-1 overflow-y-auto p-3 space-y-2">
                {visibleCards.map(c => (
                    <div key={c.id} onClick={() => { setSelectedCardId(c.id); setViewMode('detail'); }} className={`group flex items-center gap-3 p-3 rounded-xl cursor-pointer transition-all border ${selectedCardId === c.id ? 'bg-white border-indigo-500 shadow-lg' : 'bg-white border-slate-200 hover:border-indigo-300'}`}>
                        <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center text-sm font-bold text-slate-500 shrink-0">{c.lastName?.charAt(0) || '?'}</div>
                        <div className="flex-1 min-w-0">
                            <div className="text-sm font-bold truncate">{(c.firstName || c.lastName) ? `${c.firstName} ${c.lastName}` : (c.company || '未知名片')}</div>
                            <div className="text-[10px] text-slate-400 uppercase tracking-wide truncate">{c.company}</div>
                        </div>
                    </div>
                ))}
            </div>
         </div>
      </aside>

      <main className={`flex-1 flex flex-col min-w-0 relative bg-slate-100/50 ${isMobile && viewMode === 'file' ? 'hidden' : 'flex'}`}>
         {viewMode === 'search' ? <SearchPage cards={cards} onSelectCard={(id) => { setSelectedCardId(id); setViewMode('detail'); }} onBack={() => setViewMode('file')} /> : (
             <>
                 <div className="h-16 border-b bg-white/80 backdrop-blur px-6 flex items-center justify-between shrink-0">
                     <div className="flex items-center gap-4 overflow-hidden">
                         {isMobile && <button onClick={() => setViewMode('file')} className="w-8 h-8 flex items-center justify-center rounded-full bg-slate-100"><i className="fa-solid fa-arrow-left"></i></button>}
                         {formData ? <div className="flex flex-col min-w-0"><h2 className="text-base font-black truncate">{formData.lastName}{formData.firstName}</h2><span className="text-[10px] text-slate-500 uppercase">{formData.company}</span></div> : <div className="text-sm font-bold text-slate-400">尚未選擇名片</div>}
                     </div>
                     <div className="flex items-center gap-3 shrink-0">
                         {formData && (
                             <>
                                <button id="save-btn" onClick={handleSave} disabled={!isFormDirty} className={`h-9 px-5 rounded-lg text-xs font-bold uppercase transition-all ${isFormDirty ? 'bg-indigo-600 text-white shadow-md' : 'bg-slate-200 text-slate-400'}`}>儲存</button>
                                {isMobile ? <button onClick={handleShare} className="h-9 w-9 bg-indigo-50 text-indigo-600 rounded-lg flex items-center justify-center"><i className="fa-solid fa-share-nodes"></i></button> : <button onClick={handleShare} className="h-9 px-4 bg-indigo-50 text-indigo-600 rounded-lg text-xs font-bold flex items-center gap-2"><i className="fa-solid fa-share-nodes"></i> 分享引薦</button>}
                             </>
                         )}
                     </div>
                 </div>

                 <div className="flex-1 relative overflow-hidden" id="detail-panel">
                    {formData ? (
                        <div className="h-full flex flex-col md:flex-row bg-slate-50">
                            <div className="md:w-[35%] lg:w-[30%] h-[35vh] md:h-full bg-slate-900 shrink-0 border-r border-slate-200"><PanZoomImage src={formData.imageUrl || ''} /></div>
                            <div className="flex-1 h-full overflow-y-auto custom-scrollbar bg-white p-6">
                                <div className="max-w-4xl mx-auto grid grid-cols-12 gap-y-4 gap-x-6">
                                    <div className="col-span-12 p-4 bg-emerald-50/50 rounded-xl border border-emerald-100">
                                        <h4 className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest mb-2 flex items-center gap-2"><i className="fa-solid fa-quote-left"></i> 商務引薦摘要 (適合對外分享)</h4>
                                        <textarea value={formData.summary} onChange={e => updateField('summary', e.target.value)} className="w-full bg-transparent border-none text-sm font-medium text-slate-700 leading-relaxed h-32 resize-none focus:ring-0" placeholder="摘要生成中..."></textarea>
                                        <div className="text-[9px] text-emerald-400 mt-2 italic">※ 分享時會自動附上 AI 查證免責聲明</div>
                                    </div>
                                    <div className="col-span-12 md:col-span-6"><EditableField label="Last Name" value={formData.lastName} onChange={v => updateField('lastName', v)} /></div>
                                    <div className="col-span-12 md:col-span-6"><EditableField label="First Name" value={formData.firstName} onChange={v => updateField('firstName', v)} /></div>
                                    <div className="col-span-12 md:col-span-6"><EditableField label="Job Title" value={formData.title} translation={formData.translations?.title} onChange={v => updateField('title', v)} icon="fa-id-badge" /></div>
                                    <div className="col-span-12 md:col-span-6"><EditableField label="Company" value={formData.company} translation={formData.translations?.company} onChange={v => updateField('company', v)} icon="fa-building" /></div>
                                    <div className="col-span-12 md:col-span-6"><EditableField label="Email" value={formData.email} onChange={v => updateField('email', v)} icon="fa-envelope" /></div>
                                    <div className="col-span-12 md:col-span-6"><EditableField label="Phone" value={formData.phone} onChange={v => updateField('phone', v)} icon="fa-phone" /></div>
                                    <div className="col-span-12 bg-indigo-50/50 p-4 rounded-xl border border-indigo-100">
                                        <h4 className="text-[10px] font-bold text-indigo-500 uppercase tracking-widest mb-1 flex items-center gap-2"><i className="fa-solid fa-wand-magic-sparkles"></i> AI Classification Reasoning (內部參考)</h4>
                                        <p className="text-sm text-slate-600 leading-tight font-medium h-20 overflow-y-auto">{formData.reasoning}</p>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-400 p-6">
                            <div className="w-20 h-20 bg-white rounded-3xl shadow-xl flex items-center justify-center mb-6"><i className="fa-solid fa-cloud-arrow-up text-3xl text-indigo-500"></i></div>
                            <h2 className="text-xl font-bold text-slate-800">準備開始</h2>
                            <p className="text-sm text-slate-500 mt-2">請從左側選擇名片或拖放檔案以開始</p>
                        </div>
                    )}
                 </div>
             </>
         )}
      </main>
      <style>{`.custom-scrollbar::-webkit-scrollbar { width: 6px; } .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; } @keyframes h-bounce { 0%, 100% { transform: translateX(0); } 50% { transform: translateX(-25%); } } .animate-h-bounce { animation: h-bounce 1s infinite; }`}</style>
    </div>
  );
};

export default App;
